```json
{
  "root_causes": [
    {
      "service": "ts-user-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.time, round(c.duration/1e6,1) client_ms, round(s.duration/1e6,1) server_ms, round((c.duration-s.duration)/1e6,1) gap_ms, s.attr_k8s_pod_name spod FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='ts-user-service' AND c.span_name='POST' AND s.service_name='ts-auth-service' ORDER BY c.duration DESC LIMIT 15",
          "claim": "Slow user-to-auth calls show 200-650ms client-minus-server gaps while auth server spans stay near 75ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS client_posts_without_server_span, round(max(c.duration/1e6),1) AS max_client_ms FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.service_name='ts-auth-service' WHERE c.service_name='ts-user-service' AND c.span_name='POST' AND s.span_id IS NULL",
          "claim": "Several ts-user-service POST calls to auth have no matching auth server span, reaching up to ~26 s client time."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'norm' p, service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms, round(max(duration/1e6),1) max_ms FROM normal_traces WHERE span_name='POST' AND service_name='ts-user-service' GROUP BY ALL UNION ALL SELECT 'abn', service_name, span_name, count(*), round(approx_quantile(duration/1e6,0.95),1), round(max(duration/1e6),1) FROM abnormal_traces WHERE span_name='POST' AND service_name='ts-user-service' GROUP BY ALL",
          "claim": "ts-user-service outbound POST p95 rises from ~78ms normal to ~714ms abnormal, max ~26.6 s."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-user-service",
      "to": "ts-admin-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'norm' p, service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM normal_traces WHERE span_name IN ('POST /api/v1/userservice/users/register','POST /api/v1/adminuserservice/users') AND attr_span_kind='Server' GROUP BY ALL UNION ALL SELECT 'abn', service_name, span_name, count(*), round(approx_quantile(duration/1e6,0.95),1) FROM abnormal_traces WHERE span_name IN ('POST /api/v1/userservice/users/register','POST /api/v1/adminuserservice/users') AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "User register server p95 rises from ~84ms to ~719ms, and admin-user POST p95 rises from ~90ms to ~302ms."
        }
      ]
    },
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'norm' p, service_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM normal_traces WHERE span_name='POST /api/v1/adminuserservice/users' AND attr_span_kind='Server' GROUP BY ALL UNION ALL SELECT 'abn', service_name, count(*), round(approx_quantile(duration/1e6,0.95),1) FROM abnormal_traces WHERE span_name='POST /api/v1/adminuserservice/users' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "ts-ui-dashboard's POST to admin-user-service rises from ~90ms p95 to ~719ms p95 in the abnormal window."
        }
      ]
    }
  ]
}
